  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Product {\n  id                Int                @id @default(autoincrement())\n  item_code         String             @unique // e.g. \"ITEM001\"\n  name              String\n  brand             String\n  category          String\n  purchasePrice     Float\n  salePrice         Float\n  defaultDiscount   Float              @default(0)\n  stock             Int                @default(0) // Tracks total units\n  unitsPerPack      Int                @default(1) // Total Tablets per Box (stripsPerBox * tabletsPerStrip)\n  stripsPerBox      Int                @default(1) // New: How many strips in a box\n  tabletsPerStrip   Int                @default(1) // New: How many tablets in a strip\n  batches           Batch[]\n  saleItems         SaleItem[]\n  purchaseItems     PurchaseItem[]\n  transfers         Transfer[]\n  aliases           ProductAlias[]\n  productSuppliers  ProductSupplier[]\n  expectedDiscounts ExpectedDiscount[]\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n}\n\nmodel Branch {\n  id            Int        @id @default(autoincrement())\n  name          String\n  location      String\n  type          String // \"Main\" | \"Pharmacy\"\n  batches       Batch[]\n  sales         Sale[]\n  purchases     Purchase[]\n  users         User[]\n  fromTransfers Transfer[] @relation(\"FromBranch\")\n  toTransfers   Transfer[] @relation(\"ToBranch\")\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n}\n\nmodel Batch {\n  id                Int            @id @default(autoincrement())\n  batchNo           String\n  manufacturingDate DateTime?\n  expiryDate        DateTime\n  quantity          Int // Tracks total units in this batch\n  productId         Int\n  product           Product        @relation(fields: [productId], references: [id])\n  branchId          Int?\n  branch            Branch?        @relation(fields: [branchId], references: [id])\n  supplierId        Int?\n  supplier          Supplier?      @relation(fields: [supplierId], references: [id])\n  purchasePrice     Float?\n  saleItems         SaleItem[]\n  purchaseItems     PurchaseItem[]\n  createdAt         DateTime       @default(now())\n}\n\nmodel Sale {\n  id           Int        @id @default(autoincrement())\n  invoiceNo    String     @unique\n  date         DateTime   @default(now())\n  total        Float\n  tax          Float\n  discount     Float      @default(0)\n  paidAmount   Float      @default(0)\n  changeAmount Float      @default(0)\n  items        SaleItem[]\n  branchId     Int?\n  branch       Branch?    @relation(fields: [branchId], references: [id])\n  createdAt    DateTime   @default(now())\n}\n\nmodel SaleItem {\n  id        Int     @id @default(autoincrement())\n  saleId    Int\n  sale      Sale    @relation(fields: [saleId], references: [id])\n  productId Int\n  product   Product @relation(fields: [productId], references: [id])\n  batchId   Int\n  batch     Batch   @relation(fields: [batchId], references: [id])\n  quantity  Int // units sold\n  price     Float // price per unit sold (strip price or piece price)\n  isPiece   Boolean @default(false)\n}\n\nmodel Purchase {\n  id         Int            @id @default(autoincrement())\n  invoiceNo  String         @unique\n  date       DateTime       @default(now())\n  total      Float\n  supplierId Int\n  supplier   Supplier       @relation(fields: [supplierId], references: [id])\n  items      PurchaseItem[]\n  branchId   Int?\n  branch     Branch?        @relation(fields: [branchId], references: [id])\n  createdAt  DateTime       @default(now())\n}\n\nmodel PurchaseItem {\n  id         Int      @id @default(autoincrement())\n  purchaseId Int\n  purchase   Purchase @relation(fields: [purchaseId], references: [id])\n  productId  Int\n  product    Product  @relation(fields: [productId], references: [id])\n  batchId    Int\n  batch      Batch    @relation(fields: [batchId], references: [id])\n  quantity   Int\n  price      Float\n}\n\nmodel Supplier {\n  id               Int               @id @default(autoincrement())\n  name             String\n  phone            String\n  email            String\n  address          String\n  purchases        Purchase[]\n  productSuppliers ProductSupplier[]\n  batches          Batch[]\n  totalOrders      Int               @default(0)\n  lastOrder        DateTime?\n  createdAt        DateTime          @default(now())\n}\n\nmodel Settings {\n  id           Int     @id @default(1)\n  pharmacyName String\n  ownerName    String\n  phone        String\n  email        String\n  address      String\n  logo         String?\n}\n\nmodel Alert {\n  id        Int      @id @default(autoincrement())\n  type      String // expiry, stock\n  title     String\n  message   String\n  severity  String // critical, warning, info\n  resolved  Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel Transfer {\n  id           Int      @id @default(autoincrement())\n  productId    Int\n  product      Product  @relation(fields: [productId], references: [id])\n  fromBranchId Int\n  fromBranch   Branch   @relation(\"FromBranch\", fields: [fromBranchId], references: [id])\n  toBranchId   Int\n  toBranch     Branch   @relation(\"ToBranch\", fields: [toBranchId], references: [id])\n  quantity     Int\n  batchNo      String\n  date         DateTime @default(now())\n  status       String // \"Completed\", \"Pending\"\n}\n\nmodel User {\n  id        Int      @id @default(autoincrement())\n  name      String\n  email     String   @unique\n  role      String // \"Admin\" | \"Staff\"\n  branchId  Int?\n  branch    Branch?  @relation(fields: [branchId], references: [id])\n  createdAt DateTime @default(now())\n}\n\n// ================= NEW OCR & MATCHING TABLES =================\n\nmodel OCRInvoice {\n  id           Int       @id @default(autoincrement())\n  invoiceNo    String\n  supplierName String?\n  invoiceDate  DateTime?\n  totalAmount  Float?\n  rawText      String? // Raw OCR text for reference\n  status       String    @default(\"pending\") // pending, matched, reviewed\n  items        OCRItem[]\n  createdAt    DateTime  @default(now())\n}\n\nmodel OCRItem {\n  id               Int        @id @default(autoincrement())\n  ocrInvoiceId     Int\n  ocrInvoice       OCRInvoice @relation(fields: [ocrInvoiceId], references: [id])\n  rawName          String // Name as read from OCR\n  matchedProductId Int? // Linked product after matching\n  quantity         Int?\n  unitPrice        Float?\n  discount         Float?\n  totalPrice       Float?\n  batchNo          String?\n  expiryDate       DateTime?\n  status           String     @default(\"unmatched\") // unmatched, matched, manual\n  createdAt        DateTime   @default(now())\n}\n\nmodel ProductAlias {\n  id        Int      @id @default(autoincrement())\n  alias     String   @unique // OCR alternate name\n  productId Int\n  product   Product  @relation(fields: [productId], references: [id])\n  createdAt DateTime @default(now())\n}\n\nmodel ExpectedDiscount {\n  id           Int      @id @default(autoincrement())\n  productId    Int\n  product      Product  @relation(fields: [productId], references: [id])\n  supplierName String?\n  discountPct  Float // Expected discount percentage\n  bonusQty     String? // e.g. \"10+2\" bonus scheme\n  notes        String?\n  createdAt    DateTime @default(now())\n}\n\nmodel ProductSupplier {\n  id            Int      @id @default(autoincrement())\n  productId     Int\n  product       Product  @relation(fields: [productId], references: [id])\n  supplierId    Int\n  supplier      Supplier @relation(fields: [supplierId], references: [id])\n  purchasePrice Float\n  discount      Float    @default(0)\n  lastUpdated   DateTime @updatedAt\n\n  @@unique([productId, supplierId])\n}\n",
